);
CREATE UNIQUE INDEX g_retainer_late_once ON g_retainerAdjustments(json_extract(data,'$.sourceId'))
 WHERE json_extract(data,'$.kind')='late' AND json_extract(data,'$.status')!='cancelled';

CREATE TABLE g_rateWithdrawals (id TEXT PRIMARY KEY, revision TEXT NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE UNIQUE INDEX g_rate_withdrawal_once ON g_rateWithdrawals(json_extract(data,'$.rateId'));
CREATE TRIGGER g_immutable_rate_withdrawal BEFORE UPDATE ON g_rateWithdrawals BEGIN SELECT RAISE(ABORT,'immutable_rate_withdrawal'); END;

-- GOVERN-005 business audit: one append-only row per native record write, grant change, API key event,
-- packet export, agency setup and import effect, in commit order. hash seals each row into one SHA-256
-- chain (see src/gauge/audit.ts); it is filled when the next command or audit read seals pending rows.
CREATE TABLE g_audit (seq INTEGER PRIMARY KEY AUTOINCREMENT, at INTEGER NOT NULL, actor TEXT NOT NULL, role TEXT, person_id TEXT, request_key TEXT, action TEXT NOT NULL, kind TEXT NOT NULL, record_id TEXT NOT NULL, previous_revision TEXT, revision TEXT, data TEXT NOT NULL CHECK(json_valid(data)), reference TEXT, hash TEXT CHECK(hash IS NULL OR length(hash)=64));
CREATE INDEX g_audit_record ON g_audit(kind, record_id, seq);
CREATE INDEX g_audit_pending ON g_audit(seq) WHERE hash IS NULL;
-- An import effect enters the audit once per direction (apply, undo), however many sweeps see it.
CREATE UNIQUE INDEX g_audit_reference ON g_audit(action, reference) WHERE reference IS NOT NULL;

-- Native pre-tax invoice issuance and finance-recorded bank receipts.
-- No sending, tax calculation or accounting/processor verification is implied.
CREATE TABLE g_invoice_sequence (id INTEGER PRIMARY KEY CHECK(id=1), value INTEGER NOT NULL CHECK(value>=0));
CREATE TABLE g_invoices (
 id TEXT PRIMARY KEY, revision TEXT NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)),
 packet_id TEXT GENERATED ALWAYS AS (json_extract(data,'$.packetId')) STORED NOT NULL REFERENCES g_packets(id),
 engagement_id TEXT GENERATED ALWAYS AS (json_extract(data,'$.engagementId')) STORED NOT NULL REFERENCES g_engagements(id),
 client_id TEXT GENERATED ALWAYS AS (json_extract(data,'$.clientId')) STORED NOT NULL REFERENCES g_clients(id),
 number TEXT GENERATED ALWAYS AS (json_extract(data,'$.number')) STORED NOT NULL,
 currency TEXT GENERATED ALWAYS AS (json_extract(data,'$.currency')) STORED NOT NULL,
 total_minor INTEGER GENERATED ALWAYS AS (json_extract(data,'$.totalMinor')) STORED NOT NULL CHECK(typeof(total_minor)='integer' AND total_minor>0)
);
CREATE UNIQUE INDEX g_invoice_packet_once ON g_invoices(packet_id);
CREATE UNIQUE INDEX g_invoice_number_once ON g_invoices(number);
CREATE TABLE g_payments (
 id TEXT PRIMARY KEY, revision TEXT NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)),
 invoice_id TEXT GENERATED ALWAYS AS (json_extract(data,'$.invoiceId')) STORED NOT NULL REFERENCES g_invoices(id),
 engagement_id TEXT GENERATED ALWAYS AS (json_extract(data,'$.engagementId')) STORED NOT NULL REFERENCES g_engagements(id),
 currency TEXT GENERATED ALWAYS AS (json_extract(data,'$.currency')) STORED NOT NULL,
 amount_minor INTEGER GENERATED ALWAYS AS (json_extract(data,'$.amountMinor')) STORED NOT NULL CHECK(typeof(amount_minor)='integer' AND amount_minor>0),
 reference TEXT GENERATED ALWAYS AS (json_extract(data,'$.reference')) STORED NOT NULL
);
CREATE UNIQUE INDEX g_payment_receipt_once ON g_payments(invoice_id,reference);
CREATE TRIGGER g_immutable_invoice BEFORE UPDATE ON g_invoices BEGIN SELECT RAISE(ABORT,'immutable_invoice'); END;
CREATE TRIGGER g_no_invoice_delete BEFORE DELETE ON g_invoices BEGIN SELECT RAISE(ABORT,'immutable_invoice'); END;
CREATE TRIGGER g_immutable_payment BEFORE UPDATE ON g_payments BEGIN SELECT RAISE(ABORT,'immutable_payment'); END;
CREATE TRIGGER g_no_payment_delete BEFORE DELETE ON g_payments BEGIN SELECT RAISE(ABORT,'immutable_payment'); END;
CREATE TRIGGER g_payment_allocation BEFORE INSERT ON g_payments
WHEN NOT EXISTS(SELECT 1 FROM g_invoices i WHERE i.id=NEW.invoice_id AND i.engagement_id=NEW.engagement_id AND i.currency=NEW.currency AND json_extract(NEW.data,'$.date')>=json_extract(i.data,'$.issueDate') AND COALESCE((SELECT SUM(p.amount_minor) FROM g_payments p WHERE p.invoice_id=i.id),0)+NEW.amount_minor<=i.total_minor)
BEGIN SELECT RAISE(ABORT,'invalid_invoice_payment'); END;
-- Corrections to an issued document need a credit-note flow, not a new
-- preparation packet that leaves the immutable receivable unchanged.
CREATE TRIGGER g_issued_packet_correction BEFORE INSERT ON g_packets
WHEN NEW.status<>'cancelled' AND EXISTS(SELECT 1 FROM g_invoices WHERE packet_id=json_extract(NEW.data,'$.correctsPacketId'))
BEGIN SELECT RAISE(ABORT,'issued_invoice_requires_credit'); END;
CREATE TRIGGER g_issued_packet_correction_update BEFORE UPDATE ON g_packets
WHEN NEW.status<>'cancelled' AND EXISTS(SELECT 1 FROM g_invoices WHERE packet_id=json_extract(NEW.data,'$.correctsPacketId'))
BEGIN SELECT RAISE(ABORT,'issued_invoice_requires_credit'); END;

CREATE TABLE g_paymentPromises (id TEXT PRIMARY KEY, revision TEXT NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)));

-- INVOICE-004: linked credit notes (credit, discount, write-off) and void/reissue corrections.
-- An issued invoice never changes; each correction is its own immutable document once issued.
-- A correction above the owner's GOVERN-001 review limit waits as pending for another owner or finance person.
CREATE TABLE g_credit_sequence (id INTEGER PRIMARY KEY CHECK(id=1), value INTEGER NOT NULL CHECK(value>=0));
CREATE TABLE g_invoiceCorrections (
 id TEXT PRIMARY KEY, revision TEXT NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)),
 invoice_id TEXT GENERATED ALWAYS AS (json_extract(data,'$.invoiceId')) STORED NOT NULL REFERENCES g_invoices(id),
 kind TEXT GENERATED ALWAYS AS (json_extract(data,'$.type')) STORED NOT NULL CHECK(kind IN ('credit','discount','write-off','void')),
 status TEXT GENERATED ALWAYS AS (json_extract(data,'$.status')) STORED NOT NULL CHECK(status IN ('pending','issued','withdrawn')),
 currency TEXT GENERATED ALWAYS AS (json_extract(data,'$.currency')) STORED NOT NULL,
 amount_minor INTEGER GENERATED ALWAYS AS (json_extract(data,'$.amountMinor')) STORED NOT NULL CHECK(typeof(amount_minor)='integer' AND amount_minor>0),
 number TEXT GENERATED ALWAYS AS (json_extract(data,'$.number')) STORED
);
CREATE UNIQUE INDEX g_credit_number_once ON g_invoiceCorrections(number) WHERE number IS NOT NULL;
CREATE UNIQUE INDEX g_invoice_void_once ON g_invoiceCorrections(invoice_id) WHERE kind='void' AND status<>'withdrawn';
CREATE TRIGGER g_issued_correction_immutable BEFORE UPDATE ON g_invoiceCorrections WHEN OLD.status<>'pending' BEGIN SELECT RAISE(ABORT,'immutable_invoice_correction'); END;
CREATE TRIGGER g_no_correction_delete BEFORE DELETE ON g_invoiceCorrections BEGIN SELECT RAISE(ABORT,'immutable_invoice_correction'); END;
-- Issued credits never exceed what the live invoice still owes; a void needs an invoice with no receipts or credits.
CREATE TRIGGER g_correction_issue BEFORE INSERT ON g_invoiceCorrections WHEN NEW.status='issued' AND NOT EXISTS(SELECT 1 FROM g_invoices i WHERE i.id=NEW.invoice_id AND i.currency=NEW.currency
 AND NOT EXISTS(SELECT 1 FROM g_invoiceCorrections v WHERE v.invoice_id=i.id AND v.kind='void' AND v.status='issued')
 AND CASE WHEN NEW.kind='void' THEN NEW.amount_minor=i.total_minor AND NOT EXISTS(SELECT 1 FROM g_payments p WHERE p.invoice_id=i.id) AND NOT EXISTS(SELECT 1 FROM g_invoiceCorrections c WHERE c.invoice_id=i.id AND c.kind<>'void' AND c.status='issued')
  ELSE COALESCE((SELECT SUM(p.amount_minor) FROM g_payments p WHERE p.invoice_id=i.id),0)+COALESCE((SELECT SUM(c.amount_minor) FROM g_invoiceCorrections c WHERE c.invoice_id=i.id AND c.kind<>'void' AND c.status='issued'),0)+NEW.amount_minor<=i.total_minor END)
BEGIN SELECT RAISE(ABORT,'invalid_invoice_correction'); END;
CREATE TRIGGER g_correction_approve BEFORE UPDATE ON g_invoiceCorrections WHEN NEW.status='issued' AND NOT EXISTS(SELECT 1 FROM g_invoices i WHERE i.id=NEW.invoice_id AND i.currency=NEW.currency
 AND NOT EXISTS(SELECT 1 FROM g_invoiceCorrections v WHERE v.invoice_id=i.id AND v.kind='void' AND v.status='issued')
 AND CASE WHEN NEW.kind='void' THEN NEW.amount_minor=i.total_minor AND NOT EXISTS(SELECT 1 FROM g_payments p WHERE p.invoice_id=i.id) AND NOT EXISTS(SELECT 1 FROM g_invoiceCorrections c WHERE c.invoice_id=i.id AND c.kind<>'void' AND c.status='issued')
  ELSE COALESCE((SELECT SUM(p.amount_minor) FROM g_payments p WHERE p.invoice_id=i.id),0)+COALESCE((SELECT SUM(c.amount_minor) FROM g_invoiceCorrections c WHERE c.invoice_id=i.id AND c.kind<>'void' AND c.status='issued'),0)+NEW.amount_minor<=i.total_minor END)
BEGIN SELECT RAISE(ABORT,'invalid_invoice_correction'); END;
-- Receipts now count issued credits and stop at a void.
DROP TRIGGER g_payment_allocation;
CREATE TRIGGER g_payment_allocation BEFORE INSERT ON g_payments
WHEN NOT EXISTS(SELECT 1 FROM g_invoices i WHERE i.id=NEW.invoice_id AND i.engagement_id=NEW.engagement_id AND i.currency=NEW.currency AND json_extract(NEW.data,'$.date')>=json_extract(i.data,'$.issueDate')
 AND NOT EXISTS(SELECT 1 FROM g_invoiceCorrections v WHERE v.invoice_id=i.id AND v.kind='void' AND v.status='issued')
 AND COALESCE((SELECT SUM(p.amount_minor) FROM g_payments p WHERE p.invoice_id=i.id),0)+COALESCE((SELECT SUM(c.amount_minor) FROM g_invoiceCorrections c WHERE c.invoice_id=i.id AND c.kind<>'void' AND c.status='issued'),0)+NEW.amount_minor<=i.total_minor)
BEGIN SELECT RAISE(ABORT,'invalid_invoice_payment'); END;
-- A packet issues once; only an issued void lets one reissue of that exact invoice take the same packet.
DROP INDEX g_invoice_packet_once;
CREATE UNIQUE INDEX g_invoice_packet_once ON g_invoices(packet_id) WHERE json_extract(data,'$.reissueOf') IS NULL;
CREATE UNIQUE INDEX g_invoice_reissue_once ON g_invoices(json_extract(data,'$.reissueOf')) WHERE json_extract(data,'$.reissueOf') IS NOT NULL;
CREATE TRIGGER g_invoice_reissue_requires_void BEFORE INSERT ON g_invoices
WHEN json_extract(NEW.data,'$.reissueOf') IS NOT NULL AND NOT EXISTS(SELECT 1 FROM g_invoiceCorrections v JOIN g_invoices o ON o.id=v.invoice_id WHERE v.invoice_id=json_extract(NEW.data,'$.reissueOf') AND v.kind='void' AND v.status='issued' AND o.packet_id=NEW.packet_id AND o.currency=NEW.currency AND NEW.total_minor<=o.total_minor)
BEGIN SELECT RAISE(ABORT,'reissue_requires_void'); END;

-- INVOICE-006: client receipts (money received, one unique external reference each), their exact allocations
-- to one or more of the client's invoices, and finance-recorded invoice disputes.
-- A receipt never changes. An allocation is an ordinary g_payments row that names its receipt; what is not
-- allocated is the receipt's unapplied balance. Nothing here is bank or processor verified.
CREATE TABLE g_clientReceipts (
 id TEXT PRIMARY KEY, revision TEXT NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)),
 client_id TEXT GENERATED ALWAYS AS (json_extract(data,'$.clientId')) STORED NOT NULL REFERENCES g_clients(id),
 currency TEXT GENERATED ALWAYS AS (json_extract(data,'$.currency')) STORED NOT NULL,
 amount_minor INTEGER GENERATED ALWAYS AS (json_extract(data,'$.amountMinor')) STORED NOT NULL CHECK(typeof(amount_minor)='integer' AND amount_minor>0),
 reference TEXT GENERATED ALWAYS AS (json_extract(data,'$.reference')) STORED NOT NULL
);
CREATE UNIQUE INDEX g_client_receipt_reference_once ON g_clientReceipts(reference);
CREATE TRIGGER g_immutable_client_receipt BEFORE UPDATE ON g_clientReceipts BEGIN SELECT RAISE(ABORT,'immutable_client_receipt'); END;
CREATE TRIGGER g_no_client_receipt_delete BEFORE DELETE ON g_clientReceipts BEGIN SELECT RAISE(ABORT,'immutable_client_receipt'); END;
-- An allocation names a receipt of the same client and currency, is dated on or after both the receipt and
-- the invoice, and the receipt's allocations never exceed its amount.
CREATE TRIGGER g_receipt_allocation BEFORE INSERT ON g_payments
WHEN json_extract(NEW.data,'$.receiptId') IS NOT NULL AND NOT EXISTS(
 SELECT 1 FROM g_clientReceipts r JOIN g_invoices i ON i.id=NEW.invoice_id
 WHERE r.id=json_extract(NEW.data,'$.receiptId') AND r.client_id=i.client_id AND r.currency=NEW.currency
 AND r.reference=NEW.reference AND json_extract(r.data,'$.date')<=json_extract(NEW.data,'$.date')
 AND COALESCE((SELECT SUM(p.amount_minor) FROM g_payments p WHERE json_extract(p.data,'$.receiptId')=r.id),0)+NEW.amount_minor<=r.amount_minor)
BEGIN SELECT RAISE(ABORT,'invalid_receipt_allocation'); END;

CREATE TABLE g_invoiceDisputes (
 id TEXT PRIMARY KEY, revision TEXT NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)),
 invoice_id TEXT GENERATED ALWAYS AS (json_extract(data,'$.invoiceId')) STORED NOT NULL REFERENCES g_invoices(id),
 status TEXT GENERATED ALWAYS AS (json_extract(data,'$.status')) STORED NOT NULL CHECK(status IN ('open','resolved')),
 amount_minor INTEGER GENERATED ALWAYS AS (json_extract(data,'$.amountMinor')) STORED NOT NULL CHECK(typeof(amount_minor)='integer' AND amount_minor>0)
);
